{"implementation":"def solve(case):
    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case missing required fields")

    threshold = case["threshold"]
    calls = case["calls"]
    if not is_number(threshold):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    diagnostics = []
    required_call_fields = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be an object")
        for field in required_call_fields:
            if field not in call:
                raise ValueError("call missing required field: " + field)

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if not is_number(loss_without) or not is_number(loss_with):
            raise ValueError("loss fields must be numeric")
        if not isinstance(prediction_tokens, int) or isinstance(prediction_tokens, bool):
            raise ValueError("prediction_tokens must be an integer")
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens must be non-negative")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        token_weight = max(1, prediction_tokens)
        normalized_gain = (float(loss_without) - float(loss_with)) / token_weight
        rounded_gain = round(normalized_gain, 6)
        accepted = bool(parseable and rounded_gain >= float(threshold))

        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": rounded_gain,
        })

    accepted_call_ids = [item["call_id"] for item in diagnostics if item["accepted"]]
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
